#include <iostream>



#include <vector>



#include <string>



#include <sstream>



#include <cmath>



#include <algorithm>



using namespace std;



bool prime(long long x){if(x<2)return false;for(long long k=2;k*k<=x;k++)if(x%k==0)return false;return true;}



long long digitSum(long long x){if(x<0)x=-x;long long t=0;while(x){t+=x%10;x/=10;}return t;}



long long properSum(long long x){if(x<=1)return 0;long long s=1;for(long long d=2;d*d<=x;d++)if(x%d==0){s+=d;if(d!=x/d)s+=x/d;}return s;}



bool square(long long n){if(n<0)return false;long long k=(long long)sqrt((long double)n);while(k*k<n)k++;return k*k==n;}



bool triangle(long long n){if(n<=0)return false;for(long long k=1;k*(k+1)/2<=n;k++)if(k*(k+1)/2==n)return true;return false;}



bool pronic(long long n){if(n<0)return false;for(long long k=0;k*(k+1)<=n;k++)if(k*(k+1)==n)return true;return false;}



long long divSum(long long n){if(n<0)n=-n;if(n==0)return 0;long long s=0;for(long long d=1;d*d<=n;d++)if(n%d==0){s+=d;if(d*d!=n)s+=n/d;}return s;}



long long divCount(long long n){if(n<0)n=-n;if(n==0)return 0;long long count=0;for(long long d=1;d*d<=n;d++)if(n%d==0)count+=d*d==n?1:2;return count;}



long long reverseInt(long long n){long long v=n<0?-n:n,ret=0;while(v){ret=ret*10+v%10;v/=10;}return n<0?-ret:ret;}



long long fact(long long n){long long out=1;for(long long k=2;k<=n;k++)out*=k;return out;}



long long powInt(long long x,long long n){long long out=1;for(int j=0;j<n;j++)out*=x;return out;}



bool smith(long long n){if(n<=1||prime(n))return false;long long sum=0,x=n;for(long long k=2;k*k<=x;k++)while(x%k==0){sum+=digitSum(k);x/=k;}if(x>1)sum+=digitSum(x);return sum==digitSum(n);}



int main(){
int m;cin>>m;bool first=true;while(m--){long long v;cin>>v;if(pronic(v)){if(!first)cout<<' ';cout<<v;first=false;}}if(first)cout<<'-';cout<<'\n';
}
